import request from 'supertest';
import { describe, expect, it } from 'vitest';
import { createApp } from '../src/app.ts';

describe('users API', () => {
  it('creates, gets, updates, and deletes users', async () => {
    const app = createApp();
    const created = await request(app).post('/v1/users').send({ email: 'a@example.com', name: 'Alice' });
    expect(created.status).toBe(201); expect(created.headers.location).toMatch(/^\/v1\/users\/[0-9a-f-]+$/); expect(created.body.role).toBe('member');
    const id = created.body.id;
    expect((await request(app).get(`/v1/users/${id}`)).status).toBe(200);
    const updated = await request(app).patch(`/v1/users/${id}`).send({ name: 'A' });
    expect(updated.status).toBe(200); expect(updated.body.name).toBe('A'); expect(updated.body.email).toBe('a@example.com');
    expect((await request(app).delete(`/v1/users/${id}`)).status).toBe(204);
    expect((await request(app).get(`/v1/users/${id}`)).status).toBe(404);
  });
  it('enforces validation, conflicts, idempotency, and pagination', async () => {
    const app = createApp();
    const first = await request(app).post('/v1/users').set('Idempotency-Key', 'k').send({ email: 'a@example.com', name: 'A' });
    const replay = await request(app).post('/v1/users').set('Idempotency-Key', 'k').send({ email: 'a@example.com', name: 'A' });
    expect(replay.status).toBe(201); expect(replay.headers['idempotent-replayed']).toBe('true');
    expect((await request(app).post('/v1/users').send({ email: 'a@example.com', name: 'B' })).status).toBe(409);
    expect((await request(app).post('/v1/users').set('Idempotency-Key', 'k').send({ email: 'b@example.com', name: 'B' })).status).toBe(422);
    expect((await request(app).post('/v1/users').send({ email: 'bad', name: '' })).status).toBe(422);
    expect((await request(app).get('/v1/users?limit=bad')).status).toBe(422);
    expect((await request(app).get('/v1/users/not-a-uuid')).status).toBe(422);
    expect((await request(app).patch(`/v1/users/${first.body.id}`)).status).toBe(422);
    const page = await request(app).get('/v1/users?limit=1'); expect(page.status).toBe(200); expect(page.body.data).toHaveLength(1); expect(page.body.nextCursor).toBeNull();
    expect((await request(app).get('/v1/users/00000000-0000-4000-8000-000000000000')).status).toBe(404);
  });
});

